Map webcoreSemanticModel(Object document, Map evidence, int maxDepth) {
    Map acc = [occurrences: [:], truncated: false, maxDepth: maxDepth, evidence: evidence]
    if (document instanceof Map && (document as Map).s instanceof List) {
        webcoreSemanticStatements((document as Map).s as List, '$.s', 0, acc)
    }
    return [occurrences: acc.occurrences, truncated: acc.truncated]
}

void webcoreSemanticStatements(List list, String path, int depth, Map acc, String container = 'block') {
    for (int i = 0; i < list.size(); i++) {
        if (list[i] instanceof Map) webcoreSemanticStatement(list[i] as Map, path + '[' + i + ']', depth + 1, acc, container)
    }
}





void webcoreSemanticStatement(Map node, String path, int depth, Map acc, String container = 'block') {
    if (depth > (acc.maxDepth as Integer)) { acc.truncated = true; return }
    String type = (node.t instanceof String) ? (node.t as String) : "${''}"
    Set claims = [] as Set
    Set gaps = [] as Set
    Map gapReasons = (((acc.evidence as Map).gaps ?: [:]) as Map)
    boolean known = type in ['if', 'do', 'switch', 'break', 'exit', 'while', 'repeat', 'for', 'each', 'on', 'every', 'action'] ||
        gapReasons.containsKey('statement.' + type + '.not-in-increment')
    Map entry = [construct: known ? 'wc.statement.' + type : 'wc.statement.unrecognised', role: null]
    
    boolean envelope = true
    if (node.r instanceof List && (node.r as List)) { gaps << 'statement.envelope.restrictions-present'; envelope = false }
    if (node.a != '0') { gaps << 'statement.envelope.async'; envelope = false }
    if (node.containsKey('tep')) { gaps << 'statement.envelope.tep-present'; envelope = false }
    if (node.containsKey('tsp')) { gaps << 'statement.envelope.tsp-present'; envelope = false }
    if (node.tcp != 'c') { gaps << 'statement.envelope.tcp-non-default'; envelope = false }
    if (envelope) claims << 'statement.envelope.default.v1'
    
    
    
    if (node.containsKey('tep')) claims << 'statement.tep.execution-policy.v1'
    if (node.containsKey('tsp')) claims << 'statement.tsp.scheduling-policy.v1'
    if (node.tcp != null && node.tcp != 'c') claims << 'statement.tcp.cancellation-policy.v1'
    if (type == 'if') {
        entry.role = 'decision'
        claims << 'statement.if.branch-order.v1'
        gaps << 'statement.if.automatic-piston-state-unresolved'
        gaps << 'statement.if.fast-forward-resumption-unresolved'
        List branches = [[name: 'then', condition: webcoreSemanticConditionList(node, path, depth, acc, claims, gaps)]]
        List elseIfs = (node.ei instanceof List) ? (node.ei as List) : []
        for (int i = 0; i < elseIfs.size(); i++) {
            if (!(elseIfs[i] instanceof Map)) continue
            branches << [name: 'else-if[' + i + ']', condition: webcoreSemanticConditionList(elseIfs[i] as Map, path + '.ei[' + i + ']', depth, acc, claims, gaps)]
        }
        if (node.e instanceof List && (node.e as List)) branches << [name: 'else']
        entry.branches = branches
    } else if (type == 'do') {
        entry.role = 'sequential-block'
        claims << 'statement.do.sequential-block.v1'
        entry.children = (node.s instanceof List) ? (node.s as List).count { it instanceof Map } : 0
        entry.lowersStatementLevel = true
    } else if (type == 'switch') {
        entry.role = 'multi-way-decision'
        
        entry.ctp = (node.ctp == 'e') ? 'e' : 'i'
        claims << 'statement.switch.ordered-cases.v1'
        if (node.e instanceof List && (node.e as List)) claims << 'statement.switch.default.v1'
        gaps << 'statement.switch.fast-forward-unresolved'
    } else if (type == 'break') {
        if (container == 'switch-case') {
            entry.role = 'switch-scoped-control-transfer'
            claims << 'statement.break.switch-scope.v1'
            gaps << 'statement.break.fast-forward-unresolved'
        } else if (container == 'loop-body') {
            entry.role = 'loop-scoped-control-transfer'
            claims << 'statement.break.loop-scope.v1'
            gaps << 'statement.break.fast-forward-unresolved'
        } else {
            gaps << 'statement.break.container-unresolved'
        }
    } else if (type == 'exit') {
        entry.role = 'piston-terminate'
        claims << 'statement.exit.terminate-piston.v1'
        gaps << 'statement.exit.fast-forward-unresolved'
    } else if (type == 'while') {
        entry.role = 'pre-condition-loop'
        claims << 'statement.while.pre-condition-loop.v1'
        gaps << 'statement.while.fast-forward-unresolved'
        entry.condition = webcoreSemanticConditionList(node, path, depth, acc, claims, gaps)
    } else if (type == 'repeat') {
        entry.role = 'post-condition-loop'
        claims << 'statement.repeat.post-condition-loop.v1'
        gaps << 'statement.repeat.fast-forward-unresolved'
        entry.condition = webcoreSemanticConditionList(node, path, depth, acc, claims, gaps)
    } else if (type == 'for') {
        entry.role = 'step-iteration'
        claims << 'statement.for.step-iteration.v1'
        gaps << 'statement.for.fast-forward-unresolved'
    } else if (type == 'each') {
        entry.role = 'device-iteration'
        claims << 'statement.each.device-iteration.v1'
        gaps << 'statement.each.fast-forward-unresolved'
    } else if (type == 'on') {
        entry.role = 'any-event-match'
        claims << 'statement.on.any-event-match.v1'
        gaps << 'statement.on.fast-forward-unresolved'
    } else if (type == 'every') {
        entry.role = 'own-timer-only'
        claims << 'statement.every.own-timer-only.v1'
        gaps << 'statement.every.fast-forward-unresolved'
    } else if (type == 'action') {
        List taskList = (node.k instanceof List) ? (node.k as List) : []
        if (taskList.size() > 1) {
            entry.role = 'ordered-tasks'
            claims << 'statement.action.task-order.v1'
            entry.taskCount = taskList.size()
            gaps << 'statement.action.fast-forward-unresolved'
        } else {
            gaps << 'statement.action.task-order-unresolved'
        }
        List deviceList = (node.d instanceof List) ? (node.d as List) : []
        if (deviceList) {
            entry.role = 'targeted-tasks'
            claims << 'statement.action.device-list.v1'
            boolean dynamic = deviceList.size() == 1 && deviceList[0] == '$currentEventDevice'
            entry.deviceTarget = dynamic ? 'dynamic' : 'static'
            if (dynamic) gaps << 'statement.action.device-list.dynamic-unresolved'
        }
    } else {
        String gap = 'statement.' + type + '.not-in-increment'
        gaps << ((((acc.evidence as Map).gaps ?: [:]) as Map).containsKey(gap) ? gap : 'statement.unrecognised')
        webcoreSemanticConditionStatements(node.c, path, depth, acc)
    }
    Map promoted = (((acc.evidence as Map).claims ?: [:]) as Map)
    List kept = []
    for (Object c : claims) {
        if (promoted[c] == true) { kept << c } else { gaps << ('claim.' + c + '.not-promoted') }
    }
    entry.claims = kept.sort()
    entry.gaps = (gaps as List).sort()
    (acc.occurrences as Map)[path] = entry
    if (node.s instanceof List) {
        webcoreSemanticStatements(node.s as List, path + '.s', depth, acc, type in ['while', 'repeat', 'for', 'each'] ? 'loop-body' : 'block')
    }
    List elseIfLists = (node.ei instanceof List) ? (node.ei as List) : []
    for (int i = 0; i < elseIfLists.size(); i++) {
        if (elseIfLists[i] instanceof Map && (elseIfLists[i] as Map).s instanceof List) {
            webcoreSemanticStatements((elseIfLists[i] as Map).s as List, path + '.ei[' + i + '].s', depth, acc)
        }
    }
    List cases = (node.cs instanceof List) ? (node.cs as List) : []
    for (int i = 0; i < cases.size(); i++) {
        if (cases[i] instanceof Map && (cases[i] as Map).s instanceof List) {
            webcoreSemanticStatements((cases[i] as Map).s as List, path + '.cs[' + i + '].s', depth, acc, type == 'switch' ? 'switch-case' : 'block')
        }
    }
    if (node.e instanceof List) webcoreSemanticStatements(node.e as List, path + '.e', depth, acc, type == 'switch' ? 'switch-case' : 'block')
}



Map webcoreSemanticConditionList(Map owner, String path, int depth, Map acc, Set claims, Set gaps) {
    Map out = [operator: null, negated: owner.n == true, children: []]
    if (depth > (acc.maxDepth as Integer)) { acc.truncated = true; return out }
    claims << 'condition.list.negation.v1'
    if (owner.o == 'or') { out.operator = 'or'; claims << 'condition.list.operator-or.v1' } else { gaps << 'condition.operator-unproven' }
    List items = (owner.c instanceof List) ? (owner.c as List) : []
    for (int i = 0; i < items.size(); i++) {
        Object k = items[i]
        String at = path + '.c[' + i + ']'
        if (k instanceof Map && (k as Map).t == 'group') {
            Map g = k as Map
            if (g.o == 'followed by') {
                (out.children as List) << [kind: 'opaque-followed-by-group']
                claims << 'condition.followed-by.opaque-group.v1'
                gaps << 'condition.followed-by-timing-unproven'
                webcoreSemanticConditionStatements(g.c, at, depth + 1, acc)
            } else {
                List inner = (g.c instanceof List) ? (g.c as List) : []
                if (inner.any { it instanceof Map && (it as Map).t == 'group' }) gaps << 'condition.group-depth-unproven'
                (out.children as List) << ([kind: 'group'] + webcoreSemanticConditionList(g, at, depth + 1, acc, claims, gaps))
            }
        } else {
            (out.children as List) << [kind: 'opaque-condition']
            gaps << 'condition.leaf-opaque'
        }
        if (k instanceof Map) webcoreSemanticTaskLists(k as Map, at, depth, acc)
    }
    return out
}

void webcoreSemanticTaskLists(Map condition, String path, int depth, Map acc) {
    if (condition.ts instanceof List) webcoreSemanticStatements(condition.ts as List, path + '.ts', depth + 1, acc)
    if (condition.fs instanceof List) webcoreSemanticStatements(condition.fs as List, path + '.fs', depth + 1, acc)
}


void webcoreSemanticConditionStatements(Object conditions, String path, int depth, Map acc) {
    if (!(conditions instanceof List) || depth > (acc.maxDepth as Integer)) return
    List items = conditions as List
    for (int i = 0; i < items.size(); i++) {
        if (!(items[i] instanceof Map)) continue
        Map k = items[i] as Map
        String at = path + '.c[' + i + ']'
        webcoreSemanticTaskLists(k, at, depth, acc)
        if (k.t == 'group') webcoreSemanticConditionStatements(k.c, at, depth + 1, acc)
    }
}


Map webcoreSemanticAssessment(Map model, Map evidence) {
    if (!(model instanceof Map) || model.truncated == true) {
        return [status: 'not-evaluated', occurrences: 0, explained: 0, explainable: false, gaps: [], claims: []]
    }
    Map occurrences = (model.occurrences ?: [:]) as Map
    int explained = 0
    Map gapCounts = [:]
    Set claims = [] as Set
    for (Object o : occurrences.values()) {
        Map om = o as Map
        if (!(om.gaps as List)) explained++
        for (Object g : (om.gaps as List)) gapCounts[g] = ((gapCounts[g] ?: 0) as Integer) + 1
        claims.addAll(om.claims as List)
    }
    Map reasons = (evidence?.gaps ?: [:]) as Map
    return [status: 'complete', occurrences: occurrences.size(), explained: explained,
            explainable: occurrences.size() > 0 && explained == occurrences.size(),
            gaps: gapCounts.keySet().sort().collect { Object g -> [id: g, reason: reasons[g], occurrences: gapCounts[g]] },
            claims: (claims as List).sort()]
}












@Field static final String WEBCORE_COVERAGE_SCHEMA = '1'




@Field static final ConcurrentHashMap<String, Long> WEBCORE_COVERAGE_CLAIMS = new ConcurrentHashMap<>()







Map webcoreCoverageLimits() {
    return [maxAppIdLength: 12, claimTtlMs: 60000L,
            requestBudgetMs: 12000L, loopbackTimeoutSec: 6, analysisBudgetMs: 5000L]
}




Long webcoreCoverageClaim(String appId, Long stamp, Long ttlMs) {
    Long held = WEBCORE_COVERAGE_CLAIMS.putIfAbsent(appId, stamp)
    if (held == null) return stamp
    if ((stamp - held) < ttlMs) return null
    return WEBCORE_COVERAGE_CLAIMS.replace(appId, held, stamp) ? stamp : null
}

void webcoreCoverageRelease(String appId, Long stamp) {
    if (stamp != null) WEBCORE_COVERAGE_CLAIMS.remove(appId, stamp)
}





Closure webcoreCoverageDeadline(Long deadlineAt) {
    Closure expired = { Object ignored -> now() >= deadlineAt }
    return expired
}

Integer webcoreCoverageCount(Object value) { return (value instanceof Number) ? (value as Integer) : null }

String webcoreCoverageText(Object value) { return (value instanceof String) ? (value as String) : null }





Map webcoreCoverageResponse(Map body, Map constructs) {
    Map prov = (body.provenance instanceof Map) ? (body.provenance as Map) : [:]
    Map acc = (body.accounting instanceof Map) ? (body.accounting as Map) : null
    Map levels = (body.levelCounts instanceof Map) ? (body.levelCounts as Map) : [:]
    Map trunc = (body.truncation instanceof Map) ? (body.truncation as Map) : null
    Map meta = (body.meta instanceof Map) ? (body.meta as Map) : [:]

    
    
    
    
    
    
    
    
    
    Object declaredGaps = webcoreStatementShapes().evidenceGaps
    Map shapeGaps = (declaredGaps instanceof Map) ? (declaredGaps as Map) : [:]
    Map counts = [:]
    Map constructLevels = [:]
    Map occurrences = [:]
    List capped = []
    List evidenceCapped = []
    Map occurrenceIn = (body.constructOccurrences instanceof Map) ? (body.constructOccurrences as Map) : [:]
    if (body.constructCounts instanceof Map) {
        (body.constructCounts as Map).keySet().collect { "${it}" }.sort().each { String id ->
            if (!constructs.containsKey(id)) return
            Integer n = webcoreCoverageCount((body.constructCounts as Map)[id])
            Object entry = constructs[id]
            String level = (entry instanceof Map) ? webcoreCoverageText((entry as Map).level) : null
            if (n == null || !(level in ['L0', 'L1', 'L2', 'L3', 'L4', 'L5'])) return
            counts[id] = n
            Object occ = occurrenceIn[id]
            if (occ instanceof Map) {
                Integer valid = webcoreCoverageCount((occ as Map).structurallyValid)
                Integer invalid = webcoreCoverageCount((occ as Map).structurallyInvalid)
                Integer gapped = webcoreCoverageCount((occ as Map).evidenceGapped)
                if (valid != null && invalid != null && gapped != null) {
                    Map gapCounts = [:]
                    Object rawGaps = (occ as Map).evidenceGaps
                    if (rawGaps instanceof Map) {
                        (rawGaps as Map).keySet().collect { "${it}" }.sort().each { String g ->
                            Integer c = webcoreCoverageCount((rawGaps as Map)[g])
                            if (shapeGaps.containsKey(g) && c != null && c > 0) gapCounts[g] = c
                        }
                    }
                    occurrences[id] = [structurallyValid: valid, structurallyInvalid: invalid, evidenceGapped: gapped, evidenceGaps: gapCounts]
                }
            }
            String achieved = webcoreCensusAchievedLevel(level, occurrences[id], n)
            constructLevels[id] = achieved
            if (achieved == level) return
            Map o = occurrences[id] as Map
            if (o != null && o.structurallyInvalid == 0 && o.structurallyValid == n && (o.evidenceGapped as Integer) > 0) evidenceCapped << id
            else capped << id
        }
    }

    List structureRecords = []
    if (body.structureFindings instanceof List) {
        List categories = webcoreCensusStructureCategories()
        int cap = webcoreCensusLimits().maxStructureFindings as Integer
        (body.structureFindings as List).each { Object raw ->
            if (!(raw instanceof Map) || structureRecords.size() >= cap) return
            String category = webcoreCoverageText((raw as Map).category)
            if (!(category in categories)) return
            structureRecords << [path: webcoreCoverageText((raw as Map).path), category: category]
        }
    }

    List records = []
    if (body.unrecognised instanceof List) {
        (body.unrecognised as List).each { Object raw ->
            if (!(raw instanceof Map)) return
            Map r = raw as Map
            records << [path: webcoreCoverageText(r.path),
                        reason: webcoreCoverageText(r.reason),
                        nodeKind: webcoreCoverageText(r.nodeKind)]
        }
    }

    
    
    Map gapTotals = [:]
    occurrences.each { Object id, Object o ->
        ((o as Map).evidenceGaps as Map).each { Object g, Object c -> gapTotals[g] = ((gapTotals[g] ?: 0) as Integer) + (c as Integer) }
    }
    List evidenceGaps = gapTotals.keySet().sort().collect { Object g ->
        [id: g, reason: webcoreCoverageText(shapeGaps[g]), occurrences: gapTotals[g]]
    }

    
    
    
    List levelOrder = ['L0', 'L1', 'L2', 'L3', 'L4', 'L5']
    List statementIds = counts.keySet().findAll { "${it}".startsWith('wc.statement.') } as List
    Map statementAssessment = null
    if (statementIds) {
        Map totals = [occurrences: 0, structurallyValid: 0, structurallyInvalid: 0, evidenceGapped: 0]
        statementIds.each { Object id ->
            totals.occurrences = (totals.occurrences as Integer) + (counts[id] as Integer)
            Map o = occurrences[id] as Map
            if (o != null) ['structurallyValid', 'structurallyInvalid', 'evidenceGapped'].each { String f -> totals[f] = (totals[f] as Integer) + (o[f] as Integer) }
        }
        String lowest = statementIds.collect { constructLevels[it] as String }.min { levelOrder.indexOf(it) }
        statementAssessment = [level: lowest] + totals
    }
    Map nonStatementAssessment = [unrecognised: webcoreCoverageCount(body.unrecognisedOutsideStatements)]

    Map out = [
        status: webcoreCoverageText(body.status),
        appId: webcoreCoverageText(body.appId),
        registryVersion: webcoreCoverageText(body.registryVersion),
        provenance: [
            observedWebcoreVersion: webcoreCoverageText(prov.observedWebcoreVersion),
            referenceSourceCommit: webcoreCoverageText(prov.referenceSourceCommit),
            compatibilityStatus: webcoreCoverageText(prov.compatibilityStatus)
        ],
        accounting: acc == null ? null : [
            objectsVisited: webcoreCoverageCount(acc.objectsVisited),
            arraysVisited: webcoreCoverageCount(acc.arraysVisited),
            fieldsVisited: webcoreCoverageCount(acc.fieldsVisited),
            arrayElementsVisited: webcoreCoverageCount(acc.arrayElementsVisited),
            scalarsVisited: webcoreCoverageCount(acc.scalarsVisited),
            constructCandidates: webcoreCoverageCount(acc.constructCandidates),
            constructsIdentified: webcoreCoverageCount(acc.constructsIdentified),
            defaultBranchOccurrences: webcoreCoverageCount(acc.defaultBranchOccurrences)
        ],
        constructCounts: counts,
        constructLevels: constructLevels,
        constructOccurrences: occurrences,
        structurallyCapped: capped,
        evidenceCapped: evidenceCapped,
        evidenceGaps: evidenceGaps,
        statementAssessment: statementAssessment,
        nonStatementAssessment: nonStatementAssessment,
        semanticAssessment: webcoreSemanticResponse(body.semanticAssessment),
        levelCounts: [L0: webcoreCoverageCount(levels.L0), L1: webcoreCoverageCount(levels.L1),
                      L2: webcoreCoverageCount(levels.L2), L3: webcoreCoverageCount(levels.L3),
                      L4: webcoreCoverageCount(levels.L4), L5: webcoreCoverageCount(levels.L5)],
        unrecognised: records,
        unrecognisedOverflow: webcoreCoverageCount(body.unrecognisedOverflow),
        structureFindings: structureRecords,
        structureFindingsOverflow: webcoreCoverageCount(body.structureFindingsOverflow),
        truncation: trunc == null ? null : [reason: webcoreCoverageText(trunc.reason)],
        meta: [elapsedMs: webcoreCoverageCount(meta.elapsedMs),
               resultBytes: webcoreCoverageCount(meta.resultBytes),
               decoderSchema: webcoreCoverageText(meta.decoderSchema),
               cached: meta.cached == true]
    ]
    if (body.error instanceof String) out.error = body.error
    return out
}



Map webcoreSemanticResponse(Object raw) {
    Map evidence = webcoreSemanticEvidence()
    Map reasons = (evidence.gaps ?: [:]) as Map
    Map claimIds = (evidence.claims ?: [:]) as Map
    Map a = (raw instanceof Map) ? (raw as Map) : [:]
    String status = (a.status == 'complete') ? 'complete' : 'not-evaluated'
    List gaps = []
    if (a.gaps instanceof List) {
        for (Object g : (a.gaps as List)) {
            if (!(g instanceof Map)) continue
            String id = webcoreCoverageText((g as Map).id)
            Integer n = webcoreCoverageCount((g as Map).occurrences)
            if (id != null && reasons.containsKey(id) && n != null && n > 0) gaps << [id: id, reason: reasons[id], occurrences: n]
        }
    }
    List claims = []
    if (a.claims instanceof List) {
        for (Object c : (a.claims as List)) { if (c instanceof String && claimIds.containsKey(c)) claims << c }
    }
    Integer occurrences = webcoreCoverageCount(a.occurrences)
    Integer explained = webcoreCoverageCount(a.explained)
    boolean counted = status == 'complete' && occurrences != null && explained != null
    return [status: status, occurrences: counted ? occurrences : 0, explained: counted ? explained : 0,
            explainable: counted && occurrences > 0 && explained == occurrences && a.explainable == true,
            gaps: status == 'complete' ? gaps : [], claims: status == 'complete' ? claims : []]
}

String webcoreCoverageJson(Map body, Map constructs) {
    return JsonOutput.toJson(webcoreCoverageResponse(body, constructs))
}

Map webcoreCoverageOutcome(String status, String code, int http, String appId) {
    Map body = [status: status, appId: appId, registryVersion: null,
                provenance: [observedWebcoreVersion: null, referenceSourceCommit: null,
                             compatibilityStatus: 'unknown'],
                accounting: null, constructCounts: [:], constructOccurrences: [:], levelCounts: [:],
                unrecognised: [], unrecognisedOverflow: 0, structureFindings: [], structureFindingsOverflow: 0,
                truncation: null, meta: [:]]
    if (code != null) body.error = code
    return [http: http, body: body]
}

Map webcoreDecodeCoverageMapping() {
    Map result = webcoreDecodeCoverageResult("${params?.appId ?: ''}")
    return render(status: result.http as Integer, contentType: 'application/json',
                  data: webcoreCoverageJson(result.body as Map,
                                            (webcoreCensusRegistry().constructs as Map)))
}


Map webcoreDecodeCoverageResult(String rawAppId) {
    Map limits = webcoreCoverageLimits()

    
    
    clearAbandonedScan()
    if (scanEffectivelyActive()) return webcoreCoverageOutcome('busy', 'scan-active', 409, null)

    String appId = rawAppId == null ? '' : rawAppId.trim()
    if (!appId || appId.length() > (limits.maxAppIdLength as Integer) || !(appId ==~ /^[0-9]+$/)) {
        return webcoreCoverageOutcome('invalid-request', 'invalid-app-id', 400, null)
    }

    
    
    Map appInfo = (state.appInfo instanceof Map) ? (state.appInfo as Map) : [:]
    Object entry = appInfo[appId]
    if (!(entry instanceof Map)) return webcoreCoverageOutcome('invalid-request', 'unknown-app-id', 400, appId)
    if ("${(entry as Map).type ?: ''}".trim() != 'webCoRE Piston') {
        return webcoreCoverageOutcome('invalid-request', 'not-a-piston', 400, appId)
    }

    Long started = now()
    Long stamp = webcoreCoverageClaim(appId, started, limits.claimTtlMs as Long)
    if (stamp == null) return webcoreCoverageOutcome('busy', 'coverage-in-flight', 409, appId)

    try {
        Map fetched = httpFetch("${LOOPBACK_BASE}/installedapp/statusJson/${appId}",
                                limits.loopbackTimeoutSec as Integer,
                                [contentType: 'application/json'])
        if (!fetched.ok) {
            
            return fetched.timedOut ? webcoreCoverageOutcome('error', 'source-timeout', 422, appId)
                                    : webcoreCoverageOutcome('error', 'source-unavailable', 422, appId)
        }
        if (!(fetched.data instanceof Map)) return webcoreCoverageOutcome('error', 'source-malformed', 422, appId)

        Map decoded = decodeWebcorePistonDocument(fetched.data as Map)
        
        
        if (decoded.status == 'not-present') return webcoreCoverageOutcome('not-present', null, 200, appId)
        if (decoded.status != 'complete') return webcoreCoverageOutcome('error', 'decode-failed', 422, appId)

        Map registry = webcoreCensusRegistry()
        Map constructs = registry.constructs as Map
        
        
        
        Long analysisDeadline = Math.min(started + (limits.requestBudgetMs as Long),
                                         now() + (limits.analysisBudgetMs as Long))
        Map census = collectWebcoreDecodeCoverage(decoded.document, registry, webcoreCoverageDeadline(analysisDeadline),
                                                  webcoreStatementShapes())
        Map semanticModel = (census.status == 'complete') ?
            webcoreSemanticModel(decoded.document, webcoreSemanticEvidence(), webcoreCensusLimits().maxDepth as int) : null
        decoded = null

        
        
        
        if (census.status == 'truncated' &&
            ((census.truncation instanceof Map) ? (census.truncation as Map).reason : null) == 'analysis-deadline') {
            return webcoreCoverageOutcome('analysis-timeout', 'analysis-deadline', 422, appId)
        }

        Map body = [
            status: census.status,
            appId: appId,
            registryVersion: census.registryVersion,
            provenance: census.provenance,
            accounting: census.accounting,
            constructCounts: census.constructCounts,
            constructOccurrences: census.constructOccurrences,
            levelCounts: census.levelCounts,
            unrecognised: census.unrecognised,
            unrecognisedOverflow: census.unrecognisedOverflow,
            structureFindings: census.structureFindings,
            structureFindingsOverflow: census.structureFindingsOverflow,
            unrecognisedOutsideStatements: census.unrecognisedOutsideStatements,
            semanticAssessment: webcoreSemanticAssessment(semanticModel, webcoreSemanticEvidence()),
            truncation: census.truncation
        ]
        
        
        body.meta = [
            elapsedMs: (now() - started),
            resultBytes: webcoreCoverageJson(body + [meta: [:]], constructs).getBytes('UTF-8').length,
            decoderSchema: WEBCORE_COVERAGE_SCHEMA,
            cached: false
        ]
        return [http: 200, body: body]
    } catch (Exception ignored) {
        return webcoreCoverageOutcome('error', 'coverage-failed', 422, appId)
    } finally {
        webcoreCoverageRelease(appId, stamp)
    }
}






@Field static final Map WEBCORE_MIGRATION_LEVELS = [1: 'Automatic, simple', 2: 'Automatic, more steps', 3: 'A little to finish by hand',
                                                     4: 'A lot to finish by hand', 5: 'Easier to rebuild from scratch']
@Field static final int WEBCORE_MIGRATION_SIMPLE_COMPONENTS = 5


@Field static final List WEBCORE_RM_PROVEN_COLOURS = ['Blue']
@Field static final Map WEBCORE_MIGRATION_TRIGGER_ATTRS = [switch: ['on', 'off'], motion: ['active', 'inactive'], contact: ['open', 'closed']]
@Field static final Map WEBCORE_MIGRATION_LOCAL_TYPES = [string: 'String', integer: 'Number', boolean: 'Boolean']
@Field static final List WEBCORE_MIGRATION_TRIGGER_COMPARISONS = ['changes', 'changes to', 'changes away from', 'gets', 'rises', 'drops',
    'rises above', 'drops below', 'stays', 'stays equal to', 'happens daily at', 'event occurs', 'receives']
@Field static final List WEBCORE_MIGRATION_CONDITION_FIELDS = ['$', 't', 'co', 'ct', 'sm', 'ts', 'fs', 's', 'lo', 'ro', 'ro2', 'to', 'to2', 'z']
@Field static final List WEBCORE_MIGRATION_STATEMENT_FIELDS = ['$', 't', 'a', 'c', 's', 'e', 'ei', 'k', 'd', 'r', 'rop', 'o', 'z', 'di', 'tcp']
@Field static final List WEBCORE_MIGRATION_TASK_FIELDS = ['$', 'c', 'p', 'm', 'z']

String webcoreMigrationStr(Object o) { return o == null ? "null" : o.toString() }

boolean webcoreMigrationEmpty(Object v) {
    if (v == null) return true
    if (v instanceof String) return (v as String).isEmpty()
    if (v instanceof Number) return (v as Number) == 0
    if (v instanceof Boolean) return !(v as Boolean)
    if (v instanceof Collection) return (v as Collection).isEmpty()
    if (v instanceof Map) return (v as Map).isEmpty()
    return false
}

List webcoreMigrationUnmodelled(Map node, List fields) {
    return node.keySet().collect { webcoreMigrationStr(it) }.findAll { String k -> !(k in fields) && !webcoreMigrationEmpty(node[k]) }
}


String webcoreMigrationLocation(String path) {
    if (path == 'root') return 'Piston settings'
    Map names = [s: 'statement', e: 'else statement', ei: 'else if', cs: 'case', k: 'task', v: 'variable', c: 'condition']
    List parts = []
    path.split('[.]').each { String seg ->
        int open = seg.indexOf('[')
        String index = open > 0 && seg.endsWith(']') ? seg.substring(open + 1, seg.length() - 1) : ''
        if (index ==~ /^[0-9]+$/) parts << "${names[seg.substring(0, open)] ?: seg.substring(0, open)} ${(index as int) + 1}".toString()
    }
    String text = parts.join(' > ')
    return text ? text.substring(0, 1).toUpperCase() + text.substring(1) : path
}

Map webcoreMigrationAssessment(Map piston, Map hubVariableTypes, Set knownDeviceTokens) {
    List blockers = []
    List sourceProblems = []
    Closure block = { String path, String reason, String kind, String group = null, int parts = 1 ->
        blockers << [path: path, location: webcoreMigrationLocation(path), reason: reason, kind: kind, group: group, parts: parts]
    }
    
    
    Closure countConditions
    countConditions = { Object l ->
        int n = 0
        ((l instanceof List) ? (l as List) : []).each { Object c ->
            if (!(c instanceof Map)) return
            if ((c as Map).t in ['condition', 'event']) n++
            n += countConditions((c as Map).c) as int
        }
        return n
    }
    Closure countComponents
    countComponents = { Object l ->
        int n = 0
        ((l instanceof List) ? (l as List) : []).each { Object raw ->
            if (!(raw instanceof Map) || (raw as Map).di) return
            Map st = raw as Map
            if (st.t != 'action') n++
            n += countConditions(st.c) as int
            ((st.k instanceof List) ? (st.k as List) : []).each { Object k -> if (k instanceof Map && (k as Map).c != 'noop') n++ }
            ((st.ei instanceof List) ? (st.ei as List) : []).each { Object ei -> if (ei instanceof Map) n += (countConditions((ei as Map).c) as int) + (countComponents((ei as Map).s) as int) }
            n += (countComponents(st.s) as int) + (countComponents(st.e) as int)
            ((st.cs instanceof List) ? (st.cs as List) : []).each { Object cs -> if (cs instanceof Map) n += countComponents((cs as Map).s) as int }
        }
        return n
    }
    Closure componentsOf = { Map st -> Math.max(1, countComponents([st]) as int) }

    List statements = (piston.s instanceof List) ? (piston.s as List) : []
    String statementsJson = JsonOutput.toJson(statements)

    
    if (statementsJson.contains('"ok":false')) sourceProblems << 'an expression webCoRE itself marks invalid'
    (statementsJson =~ /"x":"@@([^"]+)"/).each { List m -> if (!hubVariableTypes.containsKey(m[1])) sourceProblems << "hub variable ${m[1]} does not exist".toString() }
    int unknownDevices = 0
    (statementsJson =~ /":[0-9a-f]{32}:"/).each { Object m -> String t = webcoreMigrationStr(m); if (!knownDeviceTokens.contains(t.substring(1, t.length() - 1))) unknownDevices++ }
    if (unknownDevices) sourceProblems << "${unknownDevices} device ${unknownDevices == 1 ? 'reference' : 'references'} not found on this hub".toString()
    sourceProblems = sourceProblems.unique()
    List noEquivalent = []
    if (statementsJson.contains('"o":"followed by"')) noEquivalent << 'followed-by condition group'
    if (statementsJson.contains('"t":"each"')) noEquivalent << 'for-each over devices'
    if (statementsJson.contains('"t":"for"')) noEquivalent << 'counted for loop'

    Map localType = [:]
    int localCount = 0
    ((piston.v instanceof List) ? (piston.v as List) : []).eachWithIndex { Object raw, int i ->
        if (!(raw instanceof Map)) return
        Map v = raw as Map
        String name = webcoreMigrationStr(v.n)
        String type = WEBCORE_MIGRATION_LOCAL_TYPES[webcoreMigrationStr(v.t)]
        boolean referenced = statementsJson.contains(name) || (v.v instanceof Map && (v.v as Map).t != 'c')
        if (!type) { if (referenced) block("v[${i}]".toString(), "local variable ${name} (${v.t}) has no Rule Machine type", 'structural'); return }
        localType[name] = type
        localCount++
    }
    Set globalsUsed = [] as Set
    Closure globalType = { Object x ->
        String s = webcoreMigrationStr(x)
        if (!s.startsWith('@@')) return null
        String name = s.substring(2)
        String type = hubVariableTypes[name]
        if (!type || !(type in ['String', 'Number', 'Boolean']) || !(name ==~ /^[A-Za-z][A-Za-z0-9_]{0,63}$/)) return null
        globalsUsed << name
        return type
    }
    Closure deviceOperand = { Object lo ->
        if (!(lo instanceof Map)) return false
        Map o = lo as Map
        return o.t == 'p' && o.d instanceof List && (o.d as List).size() == 1 && WEBCORE_MIGRATION_TRIGGER_ATTRS.containsKey(webcoreMigrationStr(o.a)) &&
            knownDeviceTokens.contains(webcoreMigrationStr((o.d as List)[0]))
    }
    Closure conditionModelled = { Map c ->
        !webcoreMigrationUnmodelled(c, WEBCORE_MIGRATION_CONDITION_FIELDS) && webcoreMigrationEmpty(c.ts) && webcoreMigrationEmpty(c.fs) && (c.sm in [null, '', 'auto'])
    }
    Closure normCo = { Object co -> webcoreMigrationStr(co ?: '').replace('_', ' ') }
    Closure conditionSupported = { Object raw ->
        if (!(raw instanceof Map)) return false
        Map c = raw as Map
        if (c.t != 'condition' || !conditionModelled(c)) return false
        Map ro = (c.ro instanceof Map) ? (c.ro as Map) : [:]
        if (normCo(c.co) != 'is' || ro.t != 'c') return false
        if (deviceOperand(c.lo)) return webcoreMigrationStr(ro.c) in (WEBCORE_MIGRATION_TRIGGER_ATTRS[webcoreMigrationStr((c.lo as Map).a)] as List)
        return (c.lo instanceof Map) && (c.lo as Map).t == 'x' && localType[webcoreMigrationStr((c.lo as Map).x)] == 'String'
    }
    Closure triggerSupported = { Object raw, boolean isEvent ->
        if (!(raw instanceof Map)) return false
        Map c = raw as Map
        if (!conditionModelled(c)) return false
        String co = isEvent ? 'changes' : normCo(c.co)
        Map lo = (c.lo instanceof Map) ? (c.lo as Map) : [:]
        if (lo.t == 'x' && co == 'changes') return globalType(lo.x) != null
        if (!deviceOperand(lo)) return false
        if (co == 'changes') return true
        Map ro = (c.ro instanceof Map) ? (c.ro as Map) : [:]
        return co == 'changes to' && ro.t == 'c' && webcoreMigrationStr(ro.c) in (WEBCORE_MIGRATION_TRIGGER_ATTRS[webcoreMigrationStr(lo.a)] as List)
    }

    int triggers = 0
    int ifs = 0
    int actions = 0
    boolean hasElse = false
    boolean onTriggers = false
    Closure taskSupported = { Map st, Map k ->
        if (k.m) return false
        List params = (k.p instanceof List) ? (k.p as List) : []
        String cmd = webcoreMigrationStr(k.c)
        if (cmd == 'noop') return 'noop'
        if (cmd == 'log' && params.size() >= 2 && params[0] instanceof Map && params[1] instanceof Map) {
            Map level = params[0] as Map; Map msg = params[1] as Map
            Map consoleParam = (params.size() > 2 && params[2] instanceof Map) ? (params[2] as Map) : null
            return level.t == 'c' && level.c == 'info' && msg.t == 'c' && msg.c instanceof String && msg.c &&
                (consoleParam == null || webcoreMigrationStr(consoleParam.c) == 'false')
        }
        if (cmd in ['on', 'off']) {
            List devs = (st.d instanceof List) ? (st.d as List) : []
            return !params && devs && devs.every { knownDeviceTokens.contains(webcoreMigrationStr(it)) }
        }
        if (cmd == 'setColor' && params && params[0] instanceof Map) {
            List devs = (st.d instanceof List) ? (st.d as List) : []
            String colour = webcoreMigrationStr((params[0] as Map).s ?: (params[0] as Map).c)
            boolean restEmpty = params.drop(1).every { it == null || (it instanceof Map && webcoreMigrationEmpty((it as Map).c) && webcoreMigrationEmpty((it as Map).s)) }
            return colour in WEBCORE_RM_PROVEN_COLOURS && restEmpty && devs && devs.every { knownDeviceTokens.contains(webcoreMigrationStr(it)) }
        }
        if (cmd == 'setVariable' && params.size() == 2 && params[0] instanceof Map && params[1] instanceof Map) {
            String target = webcoreMigrationStr((params[0] as Map).x)
            Map value = params[1] as Map
            if (!target.startsWith('@') && localType.containsKey(target)) {
                if (value.t == 'c') {
                    String t = localType[target]
                    return t != 'Number' || (webcoreMigrationStr(value.c) ==~ /^-?[0-9]+$/)
                }
                if (value.t == 'x' && globalType(value.x) != null) return true
            }
            String tType = globalType(target)
            if (tType == 'Number' && value.t == 'c' && (webcoreMigrationStr(value.c) ==~ /^-?[0-9]+$/)) return true
            if (tType == 'String' && value.t == 'x' && globalType(value.x) == 'String') return true
            if (tType && value.t == 'x' && localType.containsKey(webcoreMigrationStr(value.x))) return true
        }
        return false
    }

    
    Closure triggerReason = { Map c ->
        Map lo = (c.lo instanceof Map) ? (c.lo as Map) : [:]
        String co = normCo(c.co)
        if (!conditionModelled(c)) return 'IF trigger uses settings with no automatic Rule Machine build yet'
        if (lo.t == 'x') {
            String name = webcoreMigrationStr(lo.x)
            if (!name.startsWith('@@')) return 'IF trigger on a local variable has no Rule Machine equivalent'
            String type = hubVariableTypes[name.substring(2)]
            if (!type) return 'IF trigger on a hub variable this hub does not have'
            if (!(type in ['String', 'Number', 'Boolean'])) return "IF trigger on a ${type} hub variable is not proven with Rule Machine yet".toString()
            if (!(name.substring(2) ==~ /^[A-Za-z][A-Za-z0-9_]{0,63}$/)) return 'IF trigger on a hub variable whose name has spaces or symbols is not proven with Rule Machine yet'
            return "IF trigger comparison ${co} on a hub variable is not proven with Rule Machine yet".toString()
        }
        if (lo.t == 'p') {
            if (!WEBCORE_MIGRATION_TRIGGER_ATTRS.containsKey(webcoreMigrationStr(lo.a))) return "IF trigger on the ${lo.a} attribute is not proven with Rule Machine yet".toString()
            if (!(lo.d instanceof List) || (lo.d as List).size() != 1) return 'IF trigger on several devices at once is not proven with Rule Machine yet'
            return "IF trigger comparison ${co} is not proven with Rule Machine yet".toString()
        }
        return 'IF trigger on this kind of value has no automatic Rule Machine build yet'
    }
    Closure ifReason = { Map st, String base ->
        List conds = (st.c instanceof List) ? (st.c as List) : []
        List trig = conds.findAll { it instanceof Map && normCo((it as Map).co) in WEBCORE_MIGRATION_TRIGGER_COMPARISONS }
        List plain = conds.findAll { !(it in trig) }
        if (!webcoreMigrationEmpty(st.ei)) return 'IF with ELSE IF branches has no automatic Rule Machine build yet'
        if (conds.size() > 1 && st.o != 'and') return "IF with conditions joined by ${webcoreMigrationStr(st.o ?: 'or').toUpperCase()} has no automatic Rule Machine build yet".toString()
        if (trig.size() > 1) return 'IF with several triggers has no automatic Rule Machine build yet'
        if (trig && base != 's') return 'IF trigger inside another block has no automatic Rule Machine build yet'
        if (trig && !webcoreMigrationEmpty(st.e)) return 'IF trigger with an ELSE branch has no automatic Rule Machine build yet'
        if (trig && !triggerSupported(trig[0], false)) return triggerReason(trig[0] as Map)
        if (plain.size() > 1) return 'IF with several conditions has no automatic Rule Machine build yet'
        if (plain && (plain[0] as Map).t == 'group') return "IF with a condition group (${webcoreMigrationStr((plain[0] as Map).o ?: 'and').toUpperCase()}) has no automatic Rule Machine build yet".toString()
        if (plain) return "IF condition (${normCo((plain[0] as Map).co) ?: 'unknown'}) is not proven with Rule Machine yet".toString()
        return 'IF with no conditions has no automatic Rule Machine build yet'
    }

    Closure convertBlock
    convertBlock = { Object list, String base ->
        ((list instanceof List) ? (list as List) : []).eachWithIndex { Object raw, int i ->
            if (!(raw instanceof Map)) return
            Map st = raw as Map
            String path = "${base}[${i}]"
            if (st.di) return
            if (st.t in ['action', 'if', 'on']) {
                List extra = webcoreMigrationUnmodelled(st, WEBCORE_MIGRATION_STATEMENT_FIELDS)
                if (extra) { block(path, "${st.t} has unmodelled settings (${extra.join(', ')})", 'structural', null, componentsOf(st)); return }
                if (st.tcp != null && st.tcp != 'c') { block(path, "${st.t} has a non-default task cancellation policy", 'structural', null, componentsOf(st)); return }
                if (!webcoreMigrationEmpty(st.rop) && st.rop != 'and') { block(path, "${st.t} has a restriction operator", 'structural', null, componentsOf(st)); return }
            }
            if (st.t == 'on' && base == 's' && statements.size() == 1 && webcoreMigrationEmpty(st.r)) {
                List evts = (st.c instanceof List) ? (st.c as List) : []
                if (evts && evts.every { it instanceof Map && (it as Map).t == 'event' && triggerSupported(it, true) }) {
                    onTriggers = true; triggers += evts.size(); convertBlock(st.s, "${path}.s"); return
                }
            }
            if (!webcoreMigrationEmpty(st.r)) { block(path, "${st.t} uses statement restrictions", 'structural', null, componentsOf(st)); return }
            if (webcoreMigrationStr(st.a) == '1') { block(path, "${st.t} uses asynchronous execution", 'structural', null, componentsOf(st)); return }
            if (st.t == 'action') {
                ((st.k instanceof List) ? (st.k as List) : []).eachWithIndex { Object kr, int j ->
                    if (!(kr instanceof Map)) return
                    Map k = kr as Map
                    String kPath = "${path}.k[${j}]"
                    List extra = webcoreMigrationUnmodelled(k, WEBCORE_MIGRATION_TASK_FIELDS)
                    if (extra) { block(kPath, "task ${k.c} has unmodelled settings", 'structural'); return }
                    Object ok = taskSupported(st, k)
                    if (ok == 'noop') return
                    if (ok) { actions++; return }
                    block(kPath, "${k.c} is not yet supported for automatic Rule Machine migration", webcoreMigrationStr(k.c) == 'cancelTasks' ? 'structural' : 'action')
                }
                return
            }
            if (st.t == 'if' && webcoreMigrationEmpty(st.ei)) {
                List conds = (st.c instanceof List) ? (st.c as List) : []
                if (conds.size() == 1 || st.o == 'and') {
                    List trig = conds.findAll { it instanceof Map && normCo((it as Map).co) in WEBCORE_MIGRATION_TRIGGER_COMPARISONS }
                    List plain = conds.findAll { !(it in trig) }
                    boolean noElse = webcoreMigrationEmpty(st.e)
                    if (!trig && plain.size() == 1 && conditionSupported(plain[0])) {
                        ifs++; if (!noElse) hasElse = true
                        convertBlock(st.s, "${path}.s"); convertBlock(st.e, "${path}.e"); return
                    }
                    if (base == 's' && trig.size() == 1 && !plain && noElse && triggerSupported(trig[0], false)) {
                        triggers++; convertBlock(st.s, "${path}.s"); return
                    }
                    if (base == 's' && trig.size() == 1 && plain.size() == 1 && noElse && triggerSupported(trig[0], false) && conditionSupported(plain[0])) {
                        triggers++; ifs++; convertBlock(st.s, "${path}.s"); return
                    }
                }
            }
            block(path, st.t == 'if' ? ifReason(st, base) : "${st.t} statement is outside what can be rebuilt automatically".toString(), 'structural', null, componentsOf(st))
        }
    }
    convertBlock(statements, 's')
    if (triggers > 1 && !onTriggers) block('root', 'several IF triggers need webCoRE event semantics', 'structural')

    
    if (!webcoreMigrationEmpty(piston.r)) block('root', 'piston restrictions', 'structural')
    if (!webcoreMigrationEmpty(piston.rop) && piston.rop != 'and') block('root', 'piston restriction operator', 'structural')
    if (piston.o instanceof Map) (piston.o as Map).each { k, v -> if (!webcoreMigrationEmpty(v)) block('root', "piston option ${k}", 'structural') }
    piston.keySet().collect { webcoreMigrationStr(it) }.each { String k ->
        if (!(k in ['id', 'n', 'z', 's', 'v', 'o', 'r', 'rop']) && !webcoreMigrationEmpty(piston[k])) block('root', "unmodelled piston setting ${k}", 'structural')
    }

    
    List conditions = []
    boolean timerOrOn = false
    Closure collectConditions
    collectConditions = { Object l ->
        ((l instanceof List) ? (l as List) : []).each { Object c ->
            if (!(c instanceof Map)) return
            if ((c as Map).t in ['condition', 'event']) conditions << c
            collectConditions((c as Map).c)
        }
    }
    Closure walkStatements
    walkStatements = { Object l ->
        ((l instanceof List) ? (l as List) : []).each { Object raw ->
            if (!(raw instanceof Map) || (raw as Map).di) return
            Map st = raw as Map
            if (st.t in ['every', 'on']) timerOrOn = true
            collectConditions(st.c)
            ((st.ei instanceof List) ? (st.ei as List) : []).each { Object ei -> if (ei instanceof Map) { collectConditions((ei as Map).c); walkStatements((ei as Map).s) } }
            walkStatements(st.s); walkStatements(st.e)
            ((st.cs instanceof List) ? (st.cs as List) : []).each { Object cs -> if (cs instanceof Map) walkStatements((cs as Map).s) }
        }
    }
    walkStatements(statements)
    Closure isTrigger = { Map c -> c.t == 'event' || normCo(c.co) in WEBCORE_MIGRATION_TRIGGER_COMPARISONS }
    boolean wcHasTriggers = conditions.any { isTrigger(it as Map) } || timerOrOn
    Set subscribed = [] as Set
    conditions.eachWithIndex { Object raw, int conditionIndex ->
        Map c = raw as Map
        String sm = c.sm ?: 'auto'
        String group = "subscription:${conditionIndex}".toString()
        if (wcHasTriggers) {
            if (!isTrigger(c) && sm == 'always') block('root', 'a condition subscribes to events alongside the triggers', 'structural', group)
            return
        }
        if (sm == 'never') return
        [c.lo, c.ro, c.ro2].each { Object o ->
            if (!(o instanceof Map)) return
            Map om = o as Map
            if (om.t == 'c' || om.t == null || (om.t == 'x' && !webcoreMigrationStr(om.x).startsWith('@'))) return
            if (o.is(c.lo) && deviceOperand(o)) { subscribed << "${(om.d as List)[0]}|${om.a}"; return }
            block('root', "a condition subscribes to a ${om.t == 'v' ? 'virtual device' : om.t == 'x' ? 'variable' : om.t == 'p' ? 'device list' : 'value'} with no Rule Machine trigger", 'structural', group)
        }
    }
    if (!wcHasTriggers) triggers += subscribed.size()
    blockers = blockers.unique { (it.path as String) + "|" + (it.reason as String) }

    
    
    Map effortByKey = [:]
    blockers.each { Map b ->
        String r = b.reason as String
        int effort = b.kind == 'action' ? 1 :
            ((r ==~ /^(while|repeat|switch|do|every|for|each|break|exit) .*/) || r.contains('asynchronous') || r.contains('IF triggers')) ? 3 : 2
        b.effort = effort
        effortByKey[(b.group ?: "${b.path}|${r}").toString()] = effort
    }
    int points = (effortByKey.values().sum() ?: 0) as int
    Map partsByKey = [:]
    blockers.each { Map b -> partsByKey[(b.group ?: "${b.path}|${b.reason}").toString()] = b.parts as int }
    
    int outsideStatements = (partsByKey.findAll { k, v -> k.startsWith('v[') || k.startsWith('root|') || k.startsWith('subscription:') }.values().sum() ?: 0) as int
    int totalComponents = (countComponents(statements) as int) + outsideStatements
    int manualComponents = (partsByKey.values().sum() ?: 0) as int
    if (manualComponents > totalComponents) totalComponents = manualComponents

    int level
    List summary = []
    if (sourceProblems || noEquivalent) {
        level = 5
        sourceProblems.each { summary << "Fix the piston first: ${it}".toString() }
        noEquivalent.each { summary << "No Rule Machine equivalent: ${it}".toString() }
    } else if (points) {
        level = points <= 2 ? 3 : points <= 6 ? 4 : 5
        summary << "${manualComponents} of ${totalComponents} ${totalComponents == 1 ? 'component' : 'components'} ${manualComponents == 1 ? 'needs' : 'need'} doing by hand".toString()
        if (level == 5) summary << 'Rebuilding it from scratch is likely easier'
        if (actions || triggers || ifs) summary << 'Everything else can migrate automatically'
    } else {
        level = totalComponents <= WEBCORE_MIGRATION_SIMPLE_COMPONENTS ? 1 : 2
        summary << 'Automatic migration possible'
    }
    return [
        ruleMachine: [level: level, label: WEBCORE_MIGRATION_LEVELS[level], summary: summary,
                      counts: [triggers: triggers, conditions: ifs, actions: actions, blockers: blockers.size(), effortPoints: points,
                               components: totalComponents, manualComponents: manualComponents],
                      blockers: blockers.take(25).collect { [location: it.location, reason: it.reason, effort: it.effort, components: it.parts, manual: it.kind == 'action' ? 'action' : 'structure'] },
                      blockersOverflow: Math.max(0, blockers.size() - 25)],
        visualRuleBuilder: [level: null, label: 'Not assessed yet',
                            summary: ['Visual Rule Builder conversion has not been built yet, so no rating is given.']]
    ]
}

Map webcoreMigrationAssessmentMapping() {
    Map result = webcoreMigrationAssessmentResult(webcoreMigrationStr(params?.appId ?: ''))
    return render(status: result.http as Integer, contentType: 'application/json', data: JsonOutput.toJson(result.body))
}





@Field static final int MIGRATION_CACHE_MAX = 200

void cacheMigrationRating(String appId, Map rating) {
    Map cache = new LinkedHashMap((state.migrationRatingCache ?: [:]) as Map)
    Closure side = { Object engine ->
        if (!(engine instanceof Map)) return null
        Map e = engine as Map
        Map counts = (e.counts ?: [:]) as Map
        Map auto = (e.automatic ?: [:]) as Map
        return [level: e.level, label: e.label,
                reasons: ((e.summary ?: []) as List).take(3),
                partsNeedingRework: counts.manualComponents,
                
                
                components: counts.components,
                blockers: ((e.blockers ?: []) as List).take(12),
                engineName: e.engineName,
                statusesNote: e.statusesNote,
                automatic: auto ?: null,
                automaticConversion: auto.containsKey('available') ? (auto.available as Boolean) : null]
    }
    
    
    
    
    
    
    cache[appId] = [ratedAt: now(), ruleMachine: side(rating.ruleMachine), visualRuleBuilder: side(rating.visualRuleBuilder),
                    hai: side(rating.hai),
                    engineVersion: ((rating.hai ?: [:]) as Map).version,
                    appVersion: APP_VERSION]
    if (cache.size() > MIGRATION_CACHE_MAX) {
        List oldest = cache.entrySet().sort { ((it.value as Map).ratedAt ?: 0) as Long }.take(cache.size() - MIGRATION_CACHE_MAX)
        oldest.each { cache.remove(it.key) }
    }
    state.migrationRatingCache = cache
}







String haiFeedVersionForCache() {
    Map feed = (state.haiFeed ?: [:]) as Map
    
    
    
    return "${feed.capabilitiesHash ?: feed.haiVersion ?: ''}"
}




String haiStatusesNote(boolean noCapabilities, String feedState) {
    if (!noCapabilities) return 'Rule Machine parity as that engine states it, held to the statuses it publishes now'
    if (feedState == 'OFF') return 'That engine is not installed on this hub, so this column was rated from this app own equivalence table and has not been checked against what the engine can currently do'
    return 'Not determined yet'
}

Map migrationRatingsMapping() {
    Map cache = (state.migrationRatingCache ?: [:]) as Map
    Long graphAt = (state.graphCommittedAtLocal ?: 0) as Long
    
    
    String engineVersion = haiFeedVersionForCache()
    Map appInfo = (state.appInfo ?: [:]) as Map
    Map liveFeed = (state.haiFeed ?: [:]) as Map
    
    
    
    
    
    String liveNote = haiStatusesNote(((liveFeed.capabilityCount ?: 0) as Integer) == 0, "${liveFeed.state ?: ''}")
    List out = []
    appInfo.each { String appId, info ->
        if (!(info instanceof Map)) return
        if ("${(info as Map).type ?: ''}".trim() != 'webCoRE Piston') return
        Map hit = (cache[appId] ?: [:]) as Map
        Long ratedAt = (hit.ratedAt ?: 0) as Long
        
        
        
        boolean engineMoved = ratedAt && engineVersion && hit.engineVersion && "${hit.engineVersion}" != engineVersion
        
        
        
        boolean appMoved = ratedAt && "${hit.appVersion ?: ''}" != APP_VERSION
        out << [appId: appId,
                status: ratedAt ? 'complete' : 'not-rated',
                ratedAt: ratedAt ?: null,
                appVersionMoved: ratedAt ? appMoved : null,
                stale: ratedAt ? ((ratedAt < graphAt) || engineMoved) : null,
                staleReason: ratedAt ? (engineMoved ? 'engine-version' : ((ratedAt < graphAt) ? 'graph-rebuilt' : null)) : null,
                ruleMachine: hit.ruleMachine, visualRuleBuilder: hit.visualRuleBuilder,
                hai: hit.hai ? ((hit.hai as Map) + [statusesNote: liveNote]) : hit.hai]
    }
    return render(status: 200, contentType: 'application/json',
        data: JsonOutput.toJson([ratings: out, graphCommittedAt: graphAt ?: null,
                                 appVersion: APP_VERSION,
                                 
                                 
                                 
                                 
                                 lastRatedAt: (out.findAll { it.appVersionMoved != true }
                                                  .collect { (it.ratedAt ?: 0) as Long }.max() ?: 0) ?: null,
                                 rated: out.count { it.status == 'complete' }, total: out.size()]))
}

Map webcoreMigrationAssessmentResult(String rawAppId) {
    Map limits = webcoreCoverageLimits()
    clearAbandonedScan()
    if (scanEffectivelyActive()) return [http: 409, body: [status: 'busy', error: 'scan-active']]
    String appId = rawAppId == null ? '' : rawAppId.trim()
    if (!appId || appId.length() > (limits.maxAppIdLength as Integer) || !(appId ==~ /^[0-9]+$/)) {
        return [http: 400, body: [status: 'invalid-request', error: 'invalid-app-id']]
    }
    Map appInfo = (state.appInfo instanceof Map) ? (state.appInfo as Map) : [:]
    Object entry = appInfo[appId]
    if (!(entry instanceof Map) || webcoreMigrationStr((entry as Map).type ?: '').trim() != 'webCoRE Piston') {
        return [http: 400, body: [status: 'invalid-request', error: 'not-a-piston']]
    }
    String claimKey = "migration:${appId}"
    Long stamp = webcoreCoverageClaim(claimKey, now(), limits.claimTtlMs as Long)
    if (stamp == null) return [http: 409, body: [status: 'busy', error: 'assessment-in-flight']]
    try {
        Map fetched = httpFetch("${LOOPBACK_BASE}/installedapp/statusJson/${appId}", limits.loopbackTimeoutSec as Integer, [contentType: 'application/json'])
        if (!fetched.ok || !(fetched.data instanceof Map)) return [http: 422, body: [status: 'error', error: 'source-unavailable']]
        Map decoded = decodeWebcorePistonDocument(fetched.data as Map)
        if (decoded.status == 'not-present') return [http: 200, body: [status: 'not-present']]
        if (decoded.status != 'complete' || !(decoded.document instanceof Map)) return [http: 422, body: [status: 'error', error: 'decode-failed']]

        Map inventory = (((state.hubVariableInventory ?: [:]) as Map).variables ?: [:]) as Map
        Map hubVariableTypes = [:]
        inventory.each { k, v -> hubVariableTypes[webcoreMigrationStr(k)] = normalizeHubVariableType((v instanceof Map) ? webcoreMigrationStr((v as Map).type) : null) }
        String parentId = webcoreMigrationStr((entry as Map).parent ?: '')
        Map indexes = buildWebcoreDeviceHashIndexes(appInfo)
        Map parentIndex = (((indexes.resolvable ?: [:]) as Map)[parentId] ?: [:]) as Map
        Set knownTokens = parentIndex.keySet().collect { webcoreMigrationStr(it) } as Set
        Map tokenToDeviceId = [:]
        parentIndex.each { k, v -> if ("${v}" ==~ /^[0-9]+$/) tokenToDeviceId["${k}".toString()] = "${v}" as Integer }
        Map rating = webcoreMigrationRating(decoded.document as Map, hubVariableTypes, tokenToDeviceId)
        cacheMigrationRating(appId, rating)
        return [http: 200, body: [status: 'complete', appId: appId, ruleMachine: rating.ruleMachine,
                                   visualRuleBuilder: rating.visualRuleBuilder, hai: rating.hai]]
    } catch (Exception ignored) {
        return [http: 422, body: [status: 'error', error: 'assessment-failed']]
    } finally {
        webcoreCoverageRelease(claimKey, stamp)
    }
}










